CREATE TABLE IF NOT EXISTS fleet_node (id UUID NOT NULL DEFAULT gen_random_uuid(), owner_id UUID NOT NULL, namespace TEXT NOT NULL, name TEXT NOT NULL, container_id TEXT NOT NULL DEFAULT '', container_name TEXT NOT NULL DEFAULT '', daemon_id TEXT NOT NULL, image TEXT NOT NULL, spec JSONB NOT NULL DEFAULT '{}'::jsonb, target_state TEXT NOT NULL DEFAULT 'launching', observed_state TEXT NOT NULL DEFAULT '', daemon_ready BOOLEAN NOT NULL DEFAULT false, health_checked_at TIMESTAMPTZ, generation BIGINT NOT NULL DEFAULT 1, idempotency_key TEXT NOT NULL DEFAULT '', status_detail JSONB NOT NULL DEFAULT '{}'::jsonb, error TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
